using System;
using System.Collections.Generic;
using System.Linq;
using Magenheim.Core;
using UnityEngine;
namespace Magenheim.Runtime;
internal static class DeepFractureCreatureVisuals
{
 private static readonly Dictionary<int,Mesh> PrismMeshes=new();
 internal static void ApplyAnnoyanceWisp(GameObject p,ElementalAlignment a){var c=Begin(p,"annoyance-wisp",a);Prism(c.Root,"motion-core",Vector3.zero,.22f,.58f,7,c.Core);Prism(c.Root,"crystal-shell",Vector3.zero,.38f,.82f,7,c.Shell);for(var i=0;i<5;i++){var x=Mathf.PI*2f*i/5f+.28f;Prism(c.Root,"orbit-shard-"+i,new Vector3(Mathf.Cos(x)*.48f,0,Mathf.Sin(x)*.48f),.075f,.3f,5,c.Shard);}Finish(p,c,3.2f,.85f);}
 internal static void ApplyGeodeCrawler(GameObject p,ElementalAlignment a){var c=Begin(p,"geode-crawler",a);c.Root.transform.localPosition=new Vector3(0,.08f,0);Prism(c.Root,"stone-abdomen",new Vector3(0,.12f,-.18f),.43f,.72f,8,c.Shell,new Vector3(90,0,0));Prism(c.Root,"stone-thorax",new Vector3(0,.12f,.34f),.32f,.48f,7,c.Shell,new Vector3(90,0,0));Prism(c.Root,"carapace-core",new Vector3(0,.39f,-.12f),.23f,.38f,6,c.Core);for(var i=0;i<3;i++){var z=-.27f+i*.3f;Prism(c.Root,"left-leg-"+i,new Vector3(-.43f,-.04f,z),.075f,.58f,5,c.Shard,new Vector3(0,0,62));Prism(c.Root,"right-leg-"+i,new Vector3(.43f,-.04f,z),.075f,.58f,5,c.Shard,new Vector3(0,0,-62));}Finish(p,c,2.4f,.55f);}
 internal static void ApplyShardling(GameObject p,ElementalAlignment a){var c=Begin(p,"shardling",a);c.Root.transform.localPosition=new Vector3(0,.76f,0);Prism(c.Root,"locomotion-core",new Vector3(0,.12f,0),.19f,.48f,6,c.Core);Prism(c.Root,"torso-shard",new Vector3(0,.34f,0),.29f,.82f,5,c.Shell);Prism(c.Root,"head-shard",new Vector3(0,.87f,.02f),.21f,.47f,5,c.Shard);Prism(c.Root,"left-arm-blade",new Vector3(-.39f,.33f,.04f),.075f,.76f,5,c.Shard,new Vector3(0,0,-31));Prism(c.Root,"right-arm-blade",new Vector3(.39f,.33f,.04f),.075f,.76f,5,c.Shard,new Vector3(0,0,31));Prism(c.Root,"left-runner",new Vector3(-.18f,-.37f,0),.085f,.86f,5,c.Shell);Prism(c.Root,"right-runner",new Vector3(.18f,-.37f,0),.085f,.86f,5,c.Shell);Finish(p,c,2.1f,.42f);}
 internal static void ApplyCrystalParasite(GameObject p,ElementalAlignment a){var c=Begin(p,"crystal-parasite",a);c.Root.transform.localPosition=new Vector3(0,.18f,0);Prism(c.Root,"regrowth-core",new Vector3(0,.24f,-.08f),.25f,.54f,7,c.Core,new Vector3(88,0,0));for(var i=0;i<5;i++){var z=-.52f+i*.25f;Prism(c.Root,"segmented-body-"+i,new Vector3(0,.05f,z),.29f-i*.018f,.32f,7,c.Shell,new Vector3(90,0,0));}for(var i=0;i<4;i++){var z=-.38f+i*.27f;Prism(c.Root,"left-hook-"+i,new Vector3(-.3f,-.08f,z),.055f,.42f,4,c.Shard,new Vector3(0,0,66));Prism(c.Root,"right-hook-"+i,new Vector3(.3f,-.08f,z),.055f,.42f,4,c.Shard,new Vector3(0,0,-66));}Finish(p,c,2.6f,.62f);}
 internal static void ApplyCrystalRevenant(GameObject p,ElementalAlignment a){var c=Begin(p,"crystal-revenant",a);c.Root.transform.localPosition=new Vector3(0,1.05f,0);Prism(c.Root,"resistance-core",new Vector3(0,.38f,-.12f),.25f,.55f,7,c.Core);Prism(c.Root,"armored-torso",new Vector3(0,.42f,0),.48f,1.08f,7,c.Shell);Prism(c.Root,"helmet",new Vector3(0,1.18f,.02f),.34f,.55f,6,c.Shell);Prism(c.Root,"face-crystal",new Vector3(0,1.17f,.28f),.12f,.34f,5,c.Core,new Vector3(78,0,0));Prism(c.Root,"armor-core-left",new Vector3(-.45f,.58f,0),.16f,.46f,6,c.Core,new Vector3(0,0,-32));Prism(c.Root,"armor-core-right",new Vector3(.45f,.58f,0),.16f,.46f,6,c.Core,new Vector3(0,0,32));Prism(c.Root,"left-arm",new Vector3(-.58f,.12f,.02f),.13f,.95f,6,c.Shell,new Vector3(0,0,-8));Prism(c.Root,"right-arm",new Vector3(.58f,.12f,.02f),.13f,.95f,6,c.Shell,new Vector3(0,0,8));Prism(c.Root,"left-leg",new Vector3(-.22f,-.62f,0),.15f,1.05f,6,c.Shell);Prism(c.Root,"right-leg",new Vector3(.22f,-.62f,0),.15f,1.05f,6,c.Shell);for(var i=0;i<3;i++)Prism(c.Root,"back-crystal-"+i,new Vector3((i-1)*.22f,.62f,-.38f),.09f,.58f,5,c.Shard,new Vector3(-48,0,(i-1)*13));Finish(p,c,3.4f,.7f);}
 private sealed record VisualContext(GameObject Root,Renderer[] Original,Color Tint,Material Shell,Material Core,Material Shard);
 private static VisualContext Begin(GameObject p,string f,ElementalAlignment a){if(p is null)throw new ArgumentNullException(nameof(p));var o=p.GetComponentsInChildren<Renderer>(true);var s=o.Select(r=>r.sharedMaterial).FirstOrDefault(m=>m)??throw new InvalidOperationException($"Creature host '{p.name}' exposes no material source.");var root=new GameObject("magenheim.fracture.creature."+f+".visual"){layer=p.layer};root.transform.SetParent(p.transform,false);var t=ElementVisualPalette.Tint(a);return new VisualContext(root,o,t,Mat(s,f+".shell",Color.Lerp(t,new Color(.28f,.25f,.22f),.62f),.18f,.58f,.18f),Mat(s,f+".core",Color.Lerp(t,Color.white,.68f),.02f,.96f,1.35f),Mat(s,f+".shard",t,.05f,.78f,.82f));}
 private static void Finish(GameObject p,VisualContext c,float range,float intensity){var l=c.Root.AddComponent<Light>();l.color=c.Tint;l.range=range;l.intensity=intensity;foreach(var r in c.Original)if(!r.transform.IsChildOf(c.Root.transform))r.enabled=false;foreach(var lod in p.GetComponentsInChildren<LODGroup>(true))lod.enabled=false;}
 private static Material Mat(Material s,string n,Color c,float metal,float gloss,float emission){var m=new Material(s){name="magenheim.fracture.creature."+n};m.mainTexture=Texture2D.whiteTexture;if(m.HasProperty("_Color"))m.SetColor("_Color",c);if(m.HasProperty("_Metallic"))m.SetFloat("_Metallic",metal);if(m.HasProperty("_Glossiness"))m.SetFloat("_Glossiness",gloss);if(m.HasProperty("_EmissionColor")){m.SetColor("_EmissionColor",c*emission);m.EnableKeyword("_EMISSION");}m.SetOverrideTag("RenderType","Opaque");if(m.HasProperty("_ZWrite"))m.SetFloat("_ZWrite",1);m.renderQueue=2000;return m;}
 private static void Prism(GameObject root,string name,Vector3 pos,float radius,float height,int sides,Material mat,Vector3? rot=null){if(!PrismMeshes.TryGetValue(sides,out var mesh)){mesh=CreatePrismMesh(sides);PrismMeshes.Add(sides,mesh);}var part=new GameObject(name){layer=root.layer};part.transform.SetParent(root.transform,false);part.transform.localPosition=pos;part.transform.localRotation=Quaternion.Euler(rot??Vector3.zero);part.transform.localScale=new Vector3(radius*2,height,radius*2);part.AddComponent<MeshFilter>().sharedMesh=mesh;part.AddComponent<MeshRenderer>().sharedMaterial=mat;}
 private static Mesh CreatePrismMesh(int sides){var v=new List<Vector3>();var t=new List<int>();for(var i=0;i<sides;i++){var a=2*Mathf.PI*i/sides;v.Add(new Vector3(.36f*Mathf.Cos(a),-.45f,.36f*Mathf.Sin(a)));}for(var i=0;i<sides;i++){var a=2*Mathf.PI*i/sides;v.Add(new Vector3(.5f*Mathf.Cos(a),.2f,.5f*Mathf.Sin(a)));}var top=v.Count;v.Add(new Vector3(0,.68f,0));var bottom=v.Count;v.Add(new Vector3(0,-.5f,0));for(var i=0;i<sides;i++){var n=(i+1)%sides;t.AddRange(new[]{bottom,n,i,i,n,sides+i,n,sides+n,sides+i,sides+i,sides+n,top});}var m=new Mesh{name="magenheim.fracture.creature.prism."+sides,vertices=v.ToArray(),triangles=t.ToArray()};m.RecalculateNormals();m.RecalculateBounds();return m;}
}
